starterCode:
for n in range(1, 11):
    # if n is even, print it
    pass

solution:
for n in range(1, 11):
    if n % 2 == 0:
        print(n)

starterCode:
for n in range(1, 16):
    # your logic here
    pass

solution:
for n in range(1, 16):
    if n % 15 == 0:
        print("FizzBuzz")
    elif n % 3 == 0:
        print("Fizz")
    elif n % 5 == 0:
        print("Buzz")
    else:
        print(n)

class Dog:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return f"{self.name} says Woof!"

d = Dog("Rex")
print(d.speak())
